const BANK=[{"type":"MCQ","topic":"1.1","q":"Apakah maksud nutrition?","a":["Kajian ubat sahaja","Kajian anatomi sahaja","Kajian penyakit berjangkit sahaja","Kajian nutrien dalam makanan dan hubungannya dengan penggunaan badan, kesihatan dan penyakit"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:0"},{"type":"MCQ","topic":"1.1","q":"Antara berikut, yang manakah fungsi physiological food?","a":["Menyediakan tenaga","Menentukan harga makanan","Menentukan warna makanan","Menghasilkan pembungkusan"],"c":0,"points":1,"subject":"Nutrition","key":"NSNT:1"},{"type":"MCQ","topic":"1.1","q":"Antara berikut, yang manakah termasuk standard perancangan healthy diet?","a":["BMI sahaja","DDA sahaja","Food poisoning guideline sahaja","Food Guide Pyramid 2020, RDA dan Malaysian Dietary Guidelines"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:2"},{"type":"MCQ","topic":"1.1","q":"Formula BMI yang betul ialah:","a":["Berat (kg) + tinggi (m)","Berat (kg) × tinggi (m)","Tinggi (m) / berat² (kg)","Berat (kg) / tinggi² (m²)"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:3"},{"type":"MCQ","topic":"1.1","q":"BMI seorang klien 60 kg dengan tinggi 1.5 m ialah:","a":["18.0","22.5","26.7","40.0"],"c":2,"points":1,"subject":"Nutrition","key":"NSNT:4"},{"type":"SEQ","topic":"1.1","q":"Terangkan tiga fungsi food kepada tubuh/manusia.","answer":"Fungsi sosial, psikologi dan fisiologi; fungsi fisiologi termasuk tenaga, pembinaan badan, regulasi proses badan dan perlindungan penyakit.","rubric":[{"criterion":"Fungsi sosial","points":30},{"criterion":"Fungsi psikologi","points":30},{"criterion":"Fungsi fisiologi dengan contoh yang tepat","points":40}],"subject":"Nutrition","key":"NSNT:5","points":1},{"type":"SEQ","topic":"1.1","q":"Kira BMI klien 72 kg dan tinggi 1.60 m serta nyatakan maksud pengiraan.","answer":"BMI = 72/(1.60²) = 28.1 kg/m². BMI digunakan untuk menilai status berat badan berdasarkan indeks tersebut.","rubric":[{"criterion":"Formula betul","points":30},{"criterion":"Pengiraan 28.1 kg/m²","points":50},{"criterion":"Interpretasi penggunaan BMI tepat","points":20}],"subject":"Nutrition","key":"NSNT:6","points":1},{"type":"MCQ","topic":"1.2","q":"Yang manakah macronutrient?","a":["Iron dan zinc sahaja","Vitamin B dan C sahaja","Vitamin dan mineral sahaja","Karbohidrat, protein, lemak dan air"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:7"},{"type":"MCQ","topic":"1.2","q":"Serat (fiber) ialah:","a":["Mineral trace","Protein lengkap","Vitamin larut lemak","Karbohidrat kompleks yang terlalu kompleks untuk dihadam sepenuhnya"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:8"},{"type":"MCQ","topic":"1.2","q":"Fungsi utama protein yang ditekankan dalam nota ialah:","a":["Menghasilkan air","Mengawal suhu makanan","Menggantikan semua vitamin","Membina dan membaiki struktur tubuh"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:9"},{"type":"MCQ","topic":"1.2","q":"Vitamin yang larut dalam lemak termasuk kumpulan:","a":["B dan C","C sahaja","A, D, E dan K","B1, B2 dan B12"],"c":2,"points":1,"subject":"Nutrition","key":"NSNT:10"},{"type":"MCQ","topic":"1.2","q":"Mineral yang membantu pengangkutan oksigen dan pembentukan hormon tertentu ialah:","a":["Iron","Zinc","Iodine","Fluoride"],"c":0,"points":1,"subject":"Nutrition","key":"NSNT:11"},{"type":"MCQ","topic":"1.2","q":"Vitamin B12 penting untuk:","a":["Penghasilan serat","Pembentukan enamel sahaja","Menghasilkan tenaga tanpa nutrien","Pembentukan sel darah merah serta sistem saraf dan fungsi otak"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:12"},{"type":"SEQ","topic":"1.2","q":"Bezakan macronutrient dan micronutrient serta beri contoh.","answer":"Macronutrient diperlukan dalam kuantiti banyak: karbohidrat, protein, lemak dan air. Micronutrient termasuk vitamin dan mineral.","rubric":[{"criterion":"Definisi macronutrient","points":25},{"criterion":"Contoh macronutrient","points":25},{"criterion":"Definisi/contoh micronutrient","points":50}],"subject":"Nutrition","key":"NSNT:13","points":1},{"type":"SEQ","topic":"1.2","q":"Jelaskan tiga fungsi karbohidrat.","answer":"Membekalkan tenaga/regulasi glukosa, menjimatkan protein daripada digunakan sebagai tenaga, dan membantu mencegah ketosis; serat pula membantu fungsi usus dan satiety.","rubric":[{"criterion":"Tenaga/regulasi glukosa","points":35},{"criterion":"Protein sparing","points":30},{"criterion":"Pencegahan ketosis atau fungsi fiber yang tepat","points":35}],"subject":"Nutrition","key":"NSNT:14","points":1},{"type":"SEQ","topic":"1.2","q":"Terangkan nutritional assessment yang dinyatakan dalam nota.","answer":"Antara assessment: skin fold, berat badan dan skin turgor; ujian makmal termasuk FBC, plasma protein, serum electrolyte, serum iron, cholesterol, uric acid, blood glucose serta ujian urin tertentu.","rubric":[{"criterion":"Skin fold","points":25},{"criterion":"Weight","points":20},{"criterion":"Skin turgor","points":20},{"criterion":"Contoh ujian makmal yang tepat","points":35}],"subject":"Nutrition","key":"NSNT:15","points":1},{"type":"MCQ","topic":"1.3","q":"Tujuan therapeutic diet secara umum ialah:","a":["Menghapuskan semua nutrien","Menggantikan semua rawatan perubatan","Memberi makanan yang sama kepada semua klien","Mengubah diet untuk memenuhi keperluan keadaan/penyakit klien"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:16"},{"type":"MCQ","topic":"1.3","q":"Diet yang mengubah konsistensi makanan sesuai untuk:","a":["Hanya bayi","Hanya pesakit hipertensi","Semua pesakit tanpa penilaian","Keadaan yang memerlukan tekstur makanan tertentu"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:17"},{"type":"MCQ","topic":"1.3","q":"Pemilihan therapeutic diet perlu mengambil kira:","a":["Pilihan staf sahaja","Harga makanan sahaja","Warna makanan sahaja","Keadaan klinikal dan keperluan pemakanan klien"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:18"},{"type":"MCQ","topic":"1.3","q":"Diet rendah sodium biasanya berkaitan dengan kawalan:","a":["Serat sahaja","Protein sahaja","Vitamin C sahaja","Pengambilan garam/sodium"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:19"},{"type":"SEQ","topic":"1.3","q":"Terangkan prinsip pemilihan therapeutic diet untuk seorang klien.","answer":"Diet dipilih berdasarkan keadaan/diagnosis, keperluan nutrien, toleransi/kemampuan mengambil makanan dan objektif rawatan.","rubric":[{"criterion":"Keadaan/diagnosis","points":35},{"criterion":"Keperluan nutrien","points":30},{"criterion":"Toleransi dan objektif rawatan","points":35}],"subject":"Nutrition","key":"NSNT:20","points":1},{"type":"MCQ","topic":"1.4","q":"Lactose intolerance berkaitan dengan:","a":["Kekurangan iron","Keracunan logam berat","Alergi gluten semata-mata","Ketidakmampuan bertoleransi terhadap lactose"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:21"},{"type":"MCQ","topic":"1.4","q":"Food allergy ialah:","a":["Kekurangan air","Kesan biasa semua makanan","Kesan vitamin berlebihan sahaja","Hypersensitivity terhadap kandungan makanan"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:22"},{"type":"MCQ","topic":"1.4","q":"Antara berikut termasuk food safety?","a":["Membiarkan makanan terdedah","Mengabaikan kebersihan tangan","Menyimpan makanan tanpa kawalan","Pengendalian dan penyediaan makanan yang selamat"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:23"},{"type":"MCQ","topic":"1.4","q":"Gluten intolerance termasuk dalam topik:","a":["DDA","Pharmacokinetics","Medication administration","Food related illness and allergies"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:24"},{"type":"SEQ","topic":"1.4","q":"Nyatakan langkah penting food safety semasa food handling dan preparation.","answer":"Amalkan kebersihan tangan/personel, elakkan pencemaran silang, kendalikan dan sediakan makanan dengan selamat, serta patuhi garis panduan keselamatan makanan MOH.","rubric":[{"criterion":"Kebersihan tangan/personel","points":30},{"criterion":"Pencegahan pencemaran silang","points":30},{"criterion":"Pengendalian/penyediaan selamat dan garis panduan MOH","points":40}],"subject":"Nutrition","key":"NSNT:25","points":1},{"type":"MCQ","topic":"1.5","q":"Bagi neonate hingga 1 tahun, topik pemakanan merangkumi:","a":["Diet dewasa sahaja","Diet rendah sodium sahaja","Parenteral nutrition sahaja","Keperluan nutrien, breast milk, formula milk, supplementary food dan weaning diet"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:26"},{"type":"MCQ","topic":"1.5","q":"Variasi nutritional requirement perlu dibincangkan mengikut:","a":["Warna kulit sahaja","Nama penyakit sahaja","Jenis pekerjaan sahaja","Peringkat umur sepanjang life cycle"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:27"},{"type":"MCQ","topic":"1.5","q":"Antara berikut ialah peringkat yang disenaraikan dalam nota:","a":["Adult sahaja","Neonate sahaja","Middle age sahaja","Toddler, preschool, school age, adolescent dan older adult"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:28"},{"type":"SEQ","topic":"1.5","q":"Huraikan mengapa keperluan pemakanan berbeza sepanjang life cycle.","answer":"Keperluan berubah mengikut pertumbuhan, perkembangan dan peringkat umur, daripada neonate/infant hingga toddler, preschool, school age, adolescent, young adult, middle age dan older adult.","rubric":[{"criterion":"Pertumbuhan/perkembangan sebagai asas perubahan","points":35},{"criterion":"Contoh peringkat awal kanak-kanak","points":25},{"criterion":"Contoh peringkat remaja/dewasa/older adult","points":40}],"subject":"Nutrition","key":"NSNT:29","points":1},{"type":"MCQ","topic":"1.6","q":"Intervensi nursing untuk merangsang appetite termasuk:","a":["Mengabaikan pilihan klien","Menghentikan semua makanan","Memberi makanan tanpa penilaian","Mewujudkan keadaan yang membantu klien makan dan memenuhi keperluan nutrisi"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:30"},{"type":"MCQ","topic":"1.6","q":"Alternative methods meeting nutritional requirement yang dinyatakan ialah:","a":["DDA dan DOPS","IV antibiotic sahaja","Enteral dan parenteral","Oral dan topical sahaja"],"c":2,"points":1,"subject":"Nutrition","key":"NSNT:31"},{"type":"MCQ","topic":"1.6","q":"Semasa feeding helpless patient, jururawat perlu:","a":["Tidak merekod intake","Meninggalkan klien makan sendiri","Memberi makanan secepat mungkin tanpa pemerhatian","Membantu pemberian makanan mengikut keperluan dan keselamatan klien"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:32"},{"type":"MCQ","topic":"1.6","q":"Intake and output chart digunakan untuk:","a":["Mengira BMI sahaja","Menilai allergy sahaja","Menentukan jenis vitamin sahaja","Mengukur dan merekod pengambilan serta output yang berkaitan"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:33"},{"type":"SEQ","topic":"1.6","q":"Terangkan tanggungjawab jururawat sebelum, semasa dan selepas membantu feeding helpless patient.","answer":"Sebelum: nilai keadaan dan sediakan keperluan/makanan. Semasa: bantu makan dengan selamat, posisi sesuai dan pemerhatian. Selepas: pastikan keselesaan, urus peralatan dan rekod intake mengikut prosedur.","rubric":[{"criterion":"Sebelum: assessment/preparation","points":30},{"criterion":"Semasa: feeding selamat dan pemerhatian","points":40},{"criterion":"Selepas: comfort, cleanup dan documentation","points":30}],"subject":"Nutrition","key":"NSNT:34","points":1},{"type":"SEQ","topic":"1.6","q":"Bandingkan enteral dan parenteral sebagai kaedah memenuhi nutritional requirement.","answer":"Enteral memberikan nutrien melalui saluran gastrointestinal; parenteral memberikan nutrien melalui laluan bukan gastrointestinal apabila kaedah enteral tidak sesuai/berkesan.","rubric":[{"criterion":"Enteral tepat","points":40},{"criterion":"Parenteral tepat","points":40},{"criterion":"Perbezaan utama jelas","points":20}],"subject":"Nutrition","key":"NSNT:35","points":1},{"type":"MCQ","topic":"1.1","q":"Apakah maksud health dalam konteks topik nutrition?","a":["Berat badan sahaja","Jenis makanan sahaja","Jumlah kalori sahaja","Keadaan yang berkait dengan kesejahteraan dan fungsi tubuh"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:36"},{"type":"MCQ","topic":"1.2","q":"Antara berikut ialah micronutrients:","a":["Fat dan water","Protein dan water","Vitamins dan minerals","Carbohydrate dan protein"],"c":2,"points":1,"subject":"Nutrition","key":"NSNT:37"},{"type":"MCQ","topic":"1.3","q":"Therapeutic diet perlu disesuaikan dengan:","a":["Warna pinggan","Pilihan staf sahaja","Jadual lawatan sahaja","Keadaan dan keperluan klien"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:38"},{"type":"MCQ","topic":"1.6","q":"DOPS dalam topik 1.6 termasuk demonstrasi:","a":["Penyimpanan DDA","Pemberian antibiotik","Pengiraan BMI sahaja","Feeding helpless patient dan measure/record intake-output"],"c":3,"points":1,"subject":"Nutrition","key":"NSNT:39"},{"type":"SEQ","topic":"1.4","q":"Bezakan lactose intolerance, food allergy dan gluten intolerance secara ringkas.","answer":"Lactose intolerance ialah ketidakupayaan bertoleransi terhadap lactose; food allergy ialah hypersensitivity terhadap kandungan makanan; gluten intolerance ialah intolerance terhadap gluten.","rubric":[{"criterion":"Lactose intolerance","points":35},{"criterion":"Food allergy","points":35},{"criterion":"Gluten intolerance","points":30}],"subject":"Nutrition","key":"NSNT:40","points":1},{"type":"SEQ","topic":"1.5","q":"Senaraikan peringkat life cycle yang dinyatakan dalam nota selepas neonate/infant.","answer":"Toddler, preschool, school age, adolescent, young adult, middle age adult dan older adult.","rubric":[{"criterion":"Toddler/preschool/school age","points":40},{"criterion":"Adolescent/young adult","points":30},{"criterion":"Middle age/older adult","points":30}],"subject":"Nutrition","key":"NSNT:41","points":1},{"type":"SEQ","topic":"1.6","q":"Nyatakan dua alternative methods untuk memenuhi nutritional requirement.","answer":"Enteral dan parenteral.","rubric":[{"criterion":"Enteral","points":50},{"criterion":"Parenteral","points":50}],"subject":"Nutrition","key":"NSNT:42","points":1},{"type":"SEQ","topic":"1.2","q":"Nyatakan contoh mineral yang terdapat dalam nota dan satu fungsi bagi setiapnya.","answer":"Contoh: iron—membantu pengangkutan oksigen; potassium—keseimbangan cecair dan transmisi saraf/fungsi otot; iodine—pengawalan tiroid; zinc—growth, imun dan penyembuhan luka.","rubric":[{"criterion":"Sekurang-kurangnya 2 mineral tepat","points":40},{"criterion":"Fungsi tepat","points":60}],"subject":"Nutrition","key":"NSNT:43","points":1},{"type":"SEQ","topic":"1.2","q":"Terangkan dua jenis vitamin berdasarkan kelarutan.","answer":"Vitamin dibahagikan kepada water-soluble dan fat-soluble vitamins.","rubric":[{"criterion":"Water-soluble","points":50},{"criterion":"Fat-soluble","points":50}],"subject":"Nutrition","key":"NSNT:44","points":1},{"type":"CLINICAL","topic":"1.1","q":"Klien 80 kg dan tinggi 1.60 m. Kira BMI.","answer":"31.25 kg/m²","rubric":[{"criterion":"Formula BMI","points":25},{"criterion":"80 ÷ 2.56","points":25},{"criterion":"Jawapan 31.25 kg/m²","points":50}],"subject":"Nutrition","key":"NSNT:45","points":1},{"type":"CLINICAL","topic":"1.2","q":"Klien menunjukkan risiko malnutrition. Apakah data nutritional assessment yang perlu diperhatikan berdasarkan nota?","answer":"Berat badan, skin fold, skin turgor dan data makmal yang relevan seperti FBC, plasma protein, serum electrolyte dan blood glucose.","rubric":[{"criterion":"Weight","points":25},{"criterion":"Skin fold","points":20},{"criterion":"Skin turgor","points":20},{"criterion":"Contoh data makmal","points":35}],"subject":"Nutrition","key":"NSNT:46","points":1},{"type":"CLINICAL","topic":"1.2","q":"Seorang klien kurang mengambil karbohidrat. Apakah fungsi penting karbohidrat yang perlu diterangkan?","answer":"Membekalkan tenaga/regulasi glukosa, protein sparing dan membantu mencegah ketosis.","rubric":[{"criterion":"Tenaga/glukosa","points":35},{"criterion":"Protein sparing","points":30},{"criterion":"Ketosis","points":35}],"subject":"Nutrition","key":"NSNT:47","points":1},{"type":"CLINICAL","topic":"1.3","q":"Klien memerlukan diet khas kerana keadaan klinikal. Apakah pendekatan jururawat?","answer":"Kenal pasti keadaan klinikal dan keperluan nutrisi, semak diet yang diarahkan, bantu pemilihan/pemberian diet dan pantau toleransi.","rubric":[{"criterion":"Assessment keadaan","points":30},{"criterion":"Diet sesuai/arahan","points":35},{"criterion":"Pantau toleransi","points":35}],"subject":"Nutrition","key":"NSNT:48","points":1},{"type":"CLINICAL","topic":"1.4","q":"Klien mempunyai lactose intolerance. Apakah fokus pendidikan pemakanan?","answer":"Kenal pasti makanan yang mengandungi lactose, elakkan/ubah pengambilan mengikut toleransi dan pastikan keperluan nutrisi tetap dipenuhi.","rubric":[{"criterion":"Kenal pasti lactose","points":30},{"criterion":"Pengubahsuaian diet","points":35},{"criterion":"Keperluan nutrisi","points":35}],"subject":"Nutrition","key":"NSNT:49","points":1},{"type":"CLINICAL","topic":"1.4","q":"Semasa penyediaan makanan, berlaku risiko pencemaran silang. Apakah tindakan?","answer":"Hentikan amalan tidak selamat, asingkan bahan/peralatan yang tercemar, lakukan kebersihan dan ikut prosedur food safety.","rubric":[{"criterion":"Kenal pasti risiko","points":30},{"criterion":"Asingkan/bersihkan","points":35},{"criterion":"Patuhi food safety","points":35}],"subject":"Nutrition","key":"NSNT:50","points":1},{"type":"CLINICAL","topic":"1.5","q":"Ibu bertanya tentang pemakanan bayi sehingga 1 tahun. Apakah komponen yang perlu diterangkan?","answer":"Keperluan nutrien, breast milk, formula milk jika berkaitan, supplementary food dan weaning diet mengikut peringkat.","rubric":[{"criterion":"Keperluan nutrien","points":20},{"criterion":"Breast/formula milk","points":30},{"criterion":"Supplementary/weaning diet","points":50}],"subject":"Nutrition","key":"NSNT:51","points":1},{"type":"CLINICAL","topic":"1.5","q":"Seorang adolescent mempunyai keperluan pemakanan berbeza daripada older adult. Apakah prinsipnya?","answer":"Keperluan berubah mengikut peringkat umur, pertumbuhan dan perkembangan; assessment perlu disesuaikan dengan life stage.","rubric":[{"criterion":"Life stage","points":30},{"criterion":"Growth/development","points":35},{"criterion":"Assessment disesuaikan","points":35}],"subject":"Nutrition","key":"NSNT:52","points":1},{"type":"CLINICAL","topic":"1.6","q":"Klien tidak berselera. Beri tiga intervensi nursing yang munasabah.","answer":"Cipta persekitaran makan yang sesuai, beri makanan mengikut keupayaan/preference yang dibenarkan dan pantau pengambilan serta keadaan klien.","rubric":[{"criterion":"Environment/comfort","points":30},{"criterion":"Meal assistance/preference","points":35},{"criterion":"Monitor intake/condition","points":35}],"subject":"Nutrition","key":"NSNT:53","points":1},{"type":"CLINICAL","topic":"1.6","q":"Klien helpless memerlukan bantuan makan. Apakah fokus keselamatan semasa feeding?","answer":"Posisikan dan bantu klien dengan betul, beri makanan secara sesuai/berperingkat, perhatikan toleransi dan rekod intake.","rubric":[{"criterion":"Position/safety","points":35},{"criterion":"Feeding assistance","points":35},{"criterion":"Observation/documentation","points":30}],"subject":"Nutrition","key":"NSNT:54","points":1},{"type":"CLINICAL","topic":"1.6","q":"Intake chart menunjukkan pengambilan rendah. Apakah tindakan jururawat?","answer":"Nilai sebab pengambilan rendah, rangsang appetite/intervensi yang sesuai, pertimbangkan alternative method jika diperlukan dan rekod/rujuk mengikut keperluan.","rubric":[{"criterion":"Assessment sebab","points":30},{"criterion":"Intervention appetite/nutrition","points":35},{"criterion":"Record/escalate","points":35}],"subject":"Nutrition","key":"NSNT:55","points":1},{"type":"CLINICAL","topic":"1.2","q":"Klien mempunyai tanda under nutrition. Bezakan dengan over nutrition.","answer":"Under nutrition ialah kekurangan pengambilan/tenaga atau nutrien; over nutrition ialah pengambilan berlebihan dan boleh berkaitan obesity.","rubric":[{"criterion":"Under nutrition","points":50},{"criterion":"Over nutrition","points":50}],"subject":"Nutrition","key":"NSNT:56","points":1},{"type":"CLINICAL","topic":"1.2","q":"Mengapa fiber membantu fungsi usus?","answer":"Fiber menambah bulk, membantu fungsi usus normal, memperlahankan penghadaman dan meningkatkan satiety.","rubric":[{"criterion":"Bulk/usus","points":40},{"criterion":"Perlahan penghadaman","points":25},{"criterion":"Satiety","points":35}],"subject":"Nutrition","key":"NSNT:57","points":1},{"type":"CLINICAL","topic":"1.2","q":"Klien memerlukan iron daripada diet. Apakah fungsi utama iron dalam nota?","answer":"Membantu membekalkan oksigen ke otot dan membantu pembentukan hormon tertentu.","rubric":[{"criterion":"Oksigen","points":60},{"criterion":"Hormon","points":40}],"subject":"Nutrition","key":"NSNT:58","points":1},{"type":"CLINICAL","topic":"1.2","q":"Klien memerlukan iodine. Apakah fungsi yang perlu diterangkan?","answer":"Iodine membantu pengawalan tiroid.","rubric":[{"criterion":"Fungsi tiroid tepat","points":100}],"subject":"Nutrition","key":"NSNT:59","points":1},{"type":"MCQ","topic":"2.1","q":"Pharmacology ialah:","a":["Kajian pembedahan","Kajian makanan sahaja","Kajian fisiologi sahaja","Kajian/sains ubat, tindakan, penggunaan dan kesannya"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:60"},{"type":"MCQ","topic":"2.1","q":"Pharmacodynamics merujuk kepada:","a":["Cara ubat disimpan","Cara preskripsi ditulis","Apa yang badan lakukan kepada ubat","Apa yang ubat lakukan kepada badan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:61"},{"type":"MCQ","topic":"2.1","q":"Pharmacokinetics merujuk kepada:","a":["Undang-undang DDA","Kesan placebo sahaja","Apa yang badan lakukan kepada ubat","Apa yang ubat lakukan kepada badan"],"c":2,"points":1,"subject":"Pharmacology","key":"NSNT:62"},{"type":"MCQ","topic":"2.1","q":"Antara berikut termasuk proses pharmacokinetics:","a":["Allergy, ethics, justice dan veracity","Diagnosis, surgery, dressing dan feeding","Prescription, witness, storage dan audit sahaja","Absorption, distribution, metabolism dan excretion"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:63"},{"type":"MCQ","topic":"2.2","q":"Sumber natural drugs termasuk:","a":["Tablet sahaja","Capsule sahaja","Synthetic chemical sahaja","Plant, animal, mineral, microorganism dan human"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:64"},{"type":"MCQ","topic":"2.2","q":"Penggunaan ubat untuk mencegah penyakit ialah:","a":["Diagnostic","Preventive","Replacement","Symptomatic"],"c":1,"points":1,"subject":"Pharmacology","key":"NSNT:65"},{"type":"MCQ","topic":"2.3","q":"Tablet dan capsule ialah contoh:","a":["Implants sahaja","Solid preparations","Liquid preparations","Topical preparations sahaja"],"c":1,"points":1,"subject":"Pharmacology","key":"NSNT:66"},{"type":"MCQ","topic":"2.3","q":"Suspension ialah:","a":["Implant","Parenteral needle","Solid preparation","Liquid preparation"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:67"},{"type":"MCQ","topic":"2.4","q":"First-pass effect boleh:","a":["Meningkatkan semua ubat","Menukar ubat kepada vitamin","Menghapuskan semua side effects","Mengurangkan bioavailability sesetengah ubat"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:68"},{"type":"MCQ","topic":"2.4","q":"Laluan sublingual mempunyai kelebihan kerana:","a":["Hanya untuk topical","Tidak masuk circulation","Perlu melalui stomach dahulu","Sangat vascularized dan boleh memintas GI/first-pass"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:69"},{"type":"MCQ","topic":"2.4","q":"Protein binding paling berkaitan dengan:","a":["Air sahaja","Fiber sahaja","Vitamin C sahaja","Albumin dan drug yang terikat protein"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:70"},{"type":"MCQ","topic":"2.5","q":"Therapeutic effect ialah:","a":["Allergy sahaja","Medication error","Kesan toksik sahaja","Kesan yang diingini untuk tujuan rawatan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:71"},{"type":"MCQ","topic":"2.5","q":"Tolerance bermaksud:","a":["Allergy akut","Ubat tidak diserap","Pesakit menolak ubat","Respons berkurang terhadap dos yang sama selepas penggunaan tertentu"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:72"},{"type":"MCQ","topic":"2.5","q":"Agonist ialah ubat yang:","a":["Mengubah preskripsi","Tidak mempunyai tindakan","Menghalang semua receptor","Mengaktifkan/merangsang receptor untuk menghasilkan respons"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:73"},{"type":"MCQ","topic":"2.6","q":"Antara faktor dalaman yang mempengaruhi medication action ialah:","a":["Cuaca sahaja","Harga ubat sahaja","Warna label sahaja","Age, weight, sex dan physiological/pathological factors"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:74"},{"type":"MCQ","topic":"2.6","q":"Grapefruit boleh menjadi contoh:","a":["DDA record","Drug storage","Topical route","Food-drug interaction"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:75"},{"type":"MCQ","topic":"2.6","q":"Pesakit mengambil warfarin dan banyak sayuran kaya vitamin K. Ini perlu dinilai sebagai:","a":["Route error","Drug preparation","Documentation only","Food-drug interaction"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:76"},{"type":"MCQ","topic":"2.6","q":"Slow-release/enteric-coated medication biasanya:","a":["Wajib dikunyah","Wajib dihancurkan","Perlu dicampur dengan lotion","Tidak boleh dihancurkan tanpa arahan yang sesuai"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:77"},{"type":"MCQ","topic":"2.7","q":"Bactericidal bermaksud:","a":["Membunuh virus","Membunuh bakteria","Mengurangkan pain","Menghalang pembiakan sahaja"],"c":1,"points":1,"subject":"Pharmacology","key":"NSNT:78"},{"type":"MCQ","topic":"2.7","q":"Bacteriostatic bermaksud:","a":["Menghapuskan allergy","Mengurangkan blood pressure","Menghalang pembiakan bakteria","Membunuh semua bakteria serta-merta"],"c":2,"points":1,"subject":"Pharmacology","key":"NSNT:79"},{"type":"MCQ","topic":"2.7","q":"Antibiotics digunakan untuk:","a":["Virus sahaja","Trauma sahaja","Semua penyakit","Bakteria, bukan virus"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:80"},{"type":"MCQ","topic":"2.7","q":"Sebelum memberi digoxin, apex beat perlu diperiksa dan berdasarkan nota jangan beri jika:","a":["80 bpm","90 bpm","Kurang daripada 60 bpm","Lebih daripada 100 bpm"],"c":2,"points":1,"subject":"Pharmacology","key":"NSNT:81"},{"type":"MCQ","topic":"2.7","q":"Furosemide ialah contoh:","a":["Antacid","Sedative","Antiviral","Loop diuretic"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:82"},{"type":"MCQ","topic":"2.8","q":"Dangerous Drug Act 1952 berkaitan dengan kawalan:","a":["BMI","Food allergy","Makanan sahaja","Import/export/production/sale/use dangerous drugs seperti opium"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:83"},{"type":"MCQ","topic":"2.8","q":"Dangerous drugs perlu disimpan:","a":["Dalam beg pesakit","Dalam peti makanan","Di atas meja terbuka","Dalam ruang berkunci/kawalan berganda mengikut polisi"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:84"},{"type":"MCQ","topic":"2.8","q":"Pemberian dangerous drug memerlukan:","a":["Tiada rekod","Tiada semakan identiti","Pesakit pilih sendiri tanpa prescription","Prescription dan witness/checks yang ditetapkan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:85"},{"type":"MCQ","topic":"2.9","q":"Empat unsur utama malpractice ialah:","a":["Drug, dose, route dan time","Food, water, air dan sleep","Age, sex, weight dan height","Duty, breach, causal connection dan damage"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:86"},{"type":"MCQ","topic":"2.9","q":"Autonomy bermaksud:","a":["Keadilan","Berbuat baik","Berkata benar","Hak pesakit membuat keputusan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:87"},{"type":"MCQ","topic":"2.9","q":"Medication error ialah:","a":["Kesan placebo","Kesan therapeutic","Allergy semata-mata","Kesilapan yang boleh dicegah berkaitan penggunaan ubat"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:88"},{"type":"MCQ","topic":"2.10","q":"7R termasuk:","a":["Right room, meal, bed, nurse, doctor, chart, ward","Right age, sex, weight, height, food, water, sleep","Right diagnosis, surgery, dressing, feeding, bath, rest, discharge","Right patient, medication, dose, route, time, to refuse, documentation"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:89"},{"type":"MCQ","topic":"2.10","q":"Tambahan dalam 10R termasuk:","a":["Right food, sleep dan exercise","Right surgery, dressing dan discharge","Right temperature, pulse dan respiration sahaja","Right assessment, evaluation dan client education"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:90"},{"type":"MCQ","topic":"2.11.1","q":"Kawasan medication preparation sepatutnya:","a":["Gelap dan sibuk","Tidak perlu label","Dekat sumber pencemaran","Bersih, terang dan kurang gangguan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:91"},{"type":"MCQ","topic":"2.11.2","q":"IM injection diberikan ke dalam:","a":["Vein","Dermis","Muscle","Subcutaneous fat sahaja"],"c":2,"points":1,"subject":"Pharmacology","key":"NSNT:92"},{"type":"MCQ","topic":"2.11.2","q":"Angle IM dalam nota ialah:","a":["15°","30°","45°","90°"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:93"},{"type":"MCQ","topic":"2.11.2","q":"Gauge jarum IM yang dinyatakan ialah:","a":["5–8G","10–12G","20–23G","26–30G sahaja"],"c":2,"points":1,"subject":"Pharmacology","key":"NSNT:94"},{"type":"MCQ","topic":"2.11.2","q":"Jika aspirasi IM menunjukkan darah, tindakan berdasarkan nota ialah:","a":["Tambah air","Teruskan inject","Tukar kepada oral tanpa semakan","Hentikan/keluarkan dan gunakan drug baru mengikut prosedur"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:95"},{"type":"MCQ","topic":"2.11.3","q":"Eye drops perlu diletakkan pada:","a":["Ear canal","Nasal septum","Cornea sahaja","Conjunctiva, bukan cornea"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:96"},{"type":"MCQ","topic":"2.11.3","q":"Untuk ear drops adult, auricle ditarik:","a":["Up and back","Forward only","Down and back","Straight down"],"c":0,"points":1,"subject":"Pharmacology","key":"NSNT:97"},{"type":"MCQ","topic":"2.11.3","q":"Rectal suppository/enema biasanya diberi dengan klien:","a":["Standing","Left lateral","Prone sahaja","Right lateral sahaja"],"c":1,"points":1,"subject":"Pharmacology","key":"NSNT:98"},{"type":"MCQ","topic":"2.11.4","q":"Dokumentasi ubat hendaklah:","a":["Tidak perlu masa","Diubah tanpa sebab","Lewat dan subjektif","Accurate, complete, timely dan objective"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:99"},{"type":"MCQ","topic":"2.11.4","q":"Jika ubat tidak diberi kerana pesakit muntah, dokumentasi mesti:","a":["Dipadam","Dikosongkan","Menanda sebagai diberi","Mencatat ubat tidak diberi dan sebab yang tepat"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:100"},{"type":"MCQ","topic":"2.11.5","q":"Pendidikan pesakit patut merangkumi:","a":["Nama sahaja","Harga sahaja","Warna ubat sahaja","Nama, tujuan, dos, cara/waktu, side effects, adherence dan storage"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:101"},{"type":"MCQ","topic":"3.0","q":"Complementary medicine digunakan:","a":["Hanya dalam pembedahan","Bersama rawatan konvensional","Tanpa mengambil kira keselamatan","Menggantikan rawatan konvensional"],"c":1,"points":1,"subject":"Pharmacology","key":"NSNT:102"},{"type":"MCQ","topic":"3.0","q":"Alternative medicine bermaksud:","a":["DDA sahaja","Digunakan bersama sahaja","Ubat prescription sahaja","Digunakan menggantikan rawatan konvensional"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:103"},{"type":"MCQ","topic":"2.7","q":"C&S dalam konteks antibiotik membantu:","a":["Mengira BMI","Mengukur blood pressure","Menentukan route eye drops","Menentukan organisma dan sensitiviti yang berkaitan untuk pemilihan antibiotik"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:104"},{"type":"MCQ","topic":"2.1","q":"Half-life ialah:","a":["Masa peak sahaja","Masa onset sahaja","Tempoh prescription","Masa yang diperlukan untuk jumlah/kepekatan ubat berkurang kira-kira separuh"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:105"},{"type":"MCQ","topic":"2.4","q":"Drug distribution lebih cepat ke organ yang mempunyai:","a":["Bone sahaja","Skin sahaja","Adipose sahaja","Perfusi darah tinggi seperti heart, kidney, liver dan brain"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:106"},{"type":"MCQ","topic":"2.5","q":"Antagonist ialah:","a":["Menghasilkan vitamin","Meningkatkan food intake","Mengaktifkan semua receptor","Menghalang tindakan agonist/receptor response"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:107"},{"type":"MCQ","topic":"2.7","q":"Diuretics secara umum:","a":["Membunuh bakteria","Menghentikan urine","Mengurangkan semua fluid","Meningkatkan pengeluaran urine"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:108"},{"type":"MCQ","topic":"2.8","q":"Rekod DDA perlu dibuat:","a":["Tidak perlu","Sebulan kemudian","Hanya jika ada error","Segera selepas administration mengikut rekod yang ditetapkan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:109"},{"type":"MCQ","topic":"2.9","q":"Nonmaleficence bermaksud:","a":["Buat baik","Hak memilih","Berkata benar","Mengelakkan kemudaratan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:110"},{"type":"MCQ","topic":"2.11.3","q":"Nasal medication biasanya diberi dengan kepala:","a":["Menghadap lantai","Sentiasa ke bawah","Tidak perlu posisi","Sedikit ke belakang mengikut teknik"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:111"},{"type":"MCQ","topic":"2.11.3","q":"Pessary dimasukkan ke:","a":["Cornea","External ear","Nasal cavity","Posterior fornix"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:112"},{"type":"MCQ","topic":"2.11.4","q":"Tanda/signature dokumentasi hendaklah dibuat:","a":["Bila-bila masa","Tanpa melihat pesakit","Sebelum menyediakan ubat sahaja","Selepas memastikan oral medication telah ditelan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:113"},{"type":"MCQ","topic":"2.11.5","q":"Pesakit yang mengambil ubat menyebabkan sedation patut dinasihatkan:","a":["Tambah dos","Memandu lebih laju","Hentikan semua ubat","Elak memandu jika terjejas/mengantuk dan ikut arahan"],"c":3,"points":1,"subject":"Pharmacology","key":"NSNT:114"},{"type":"SEQ","topic":"2.1","q":"Terangkan pharmacology, pharmacodynamics dan pharmacokinetics.","answer":"Pharmacology ialah kajian/sains ubat, tindakan, penggunaan dan kesannya. Pharmacodynamics ialah apa yang ubat lakukan kepada badan. Pharmacokinetics ialah apa yang badan lakukan kepada ubat.","rubric":[{"criterion":"Pharmacology","points":30},{"criterion":"Pharmacodynamics","points":35},{"criterion":"Pharmacokinetics","points":35}],"subject":"Pharmacology","key":"NSNT:115","points":1},{"type":"SEQ","topic":"2.1","q":"Nyatakan empat proses ADME.","answer":"Absorption, distribution, metabolism dan excretion.","rubric":[{"criterion":"Absorption","points":25},{"criterion":"Distribution","points":25},{"criterion":"Metabolism","points":25},{"criterion":"Excretion","points":25}],"subject":"Pharmacology","key":"NSNT:116","points":1},{"type":"SEQ","topic":"2.2","q":"Nyatakan sumber natural drugs dan tiga kegunaan ubat.","answer":"Sumber: plant, animal, mineral, microorganism, human. Kegunaan boleh termasuk symptomatic, preventive, diagnostic, curative, health maintenance, contraceptive dan replacement.","rubric":[{"criterion":"Sekurang-kurangnya 4 sumber tepat","points":50},{"criterion":"Sekurang-kurangnya 3 kegunaan tepat","points":50}],"subject":"Pharmacology","key":"NSNT:117","points":1},{"type":"SEQ","topic":"2.3","q":"Bezakan solid dan liquid drug preparations dengan contoh.","answer":"Solid: tablet, caplet, capsule, lozenge, suppository/pessary. Liquid: solution, suspension, emulsion.","rubric":[{"criterion":"Solid tepat + contoh","points":50},{"criterion":"Liquid tepat + contoh","points":50}],"subject":"Pharmacology","key":"NSNT:118","points":1},{"type":"SEQ","topic":"2.4","q":"Terangkan first-pass effect dan bioavailability.","answer":"First-pass metabolism boleh mengurangkan jumlah ubat yang sampai ke systemic circulation selepas oral administration, lalu mempengaruhi bioavailability.","rubric":[{"criterion":"First-pass tepat","points":50},{"criterion":"Kaitan bioavailability/systemic circulation","points":50}],"subject":"Pharmacology","key":"NSNT:119","points":1},{"type":"SEQ","topic":"2.4","q":"Terangkan protein binding dan free drug.","answer":"Sesetengah ubat terikat kepada protein seperti albumin; free/unbound drug ialah bahagian yang tersedia untuk menghasilkan tindakan.","rubric":[{"criterion":"Protein binding/albumin","points":40},{"criterion":"Free drug aktif/tersedia","points":60}],"subject":"Pharmacology","key":"NSNT:120","points":1},{"type":"SEQ","topic":"2.5","q":"Bezakan therapeutic, side, adverse dan toxic effects.","answer":"Therapeutic ialah kesan diingini; side effect ialah kesan tambahan yang tidak diingini; adverse effect ialah unwanted harmful response; toxicity ialah kesan berbahaya akibat jumlah/kepekatan berlebihan atau keadaan berkaitan.","rubric":[{"criterion":"Therapeutic","points":25},{"criterion":"Side","points":20},{"criterion":"Adverse","points":25},{"criterion":"Toxicity","points":30}],"subject":"Pharmacology","key":"NSNT:121","points":1},{"type":"SEQ","topic":"2.6","q":"Nyatakan faktor yang mempengaruhi medication action.","answer":"Faktor dalaman: age, weight, sex, psychological, physiological/pathological, genetic/cultural/racial. Faktor luaran: ubat/suplemen/herba lain, adherence, route/time, storage dan drug-drug/food/disease interactions.","rubric":[{"criterion":"Faktor dalaman","points":50},{"criterion":"Faktor luaran","points":50}],"subject":"Pharmacology","key":"NSNT:122","points":1},{"type":"SEQ","topic":"2.7","q":"Bezakan bactericidal dan bacteriostatic serta kaitkan dengan resistance.","answer":"Bactericidal membunuh bakteria; bacteriostatic menghalang pembiakan. Penggunaan antibiotik yang tidak sesuai boleh menyumbang kepada resistance.","rubric":[{"criterion":"Bactericidal","points":35},{"criterion":"Bacteriostatic","points":35},{"criterion":"Resistance","points":30}],"subject":"Pharmacology","key":"NSNT:123","points":1},{"type":"SEQ","topic":"2.7","q":"Terangkan perkara penting semasa pemberian digoxin berdasarkan nota.","answer":"Periksa apex beat; jangan beri jika kurang 60 bpm seperti dinyatakan dalam nota; pantau tanda toxicity.","rubric":[{"criterion":"Apex beat","points":30},{"criterion":"Hold jika <60 bpm","points":40},{"criterion":"Monitor toxicity","points":30}],"subject":"Pharmacology","key":"NSNT:124","points":1},{"type":"SEQ","topic":"2.7","q":"Terangkan kesan utama furosemide dan dua komplikasi yang perlu dipantau.","answer":"Furosemide meningkatkan urine; komplikasi termasuk dehydration, hypokalemia dan hypotension.","rubric":[{"criterion":"Diuresis/increased urine","points":35},{"criterion":"Dehydration","points":20},{"criterion":"Hypokalemia","points":25},{"criterion":"Hypotension","points":20}],"subject":"Pharmacology","key":"NSNT:125","points":1},{"type":"SEQ","topic":"2.8","q":"Terangkan storage dan kawalan stok dangerous drugs.","answer":"Simpan dalam ruang berkunci/kawalan berganda mengikut polisi; akses dikawal; stok diperiksa setiap shift; semak expiry/warna dan label/storage yang sesuai.","rubric":[{"criterion":"Locked/double control","points":30},{"criterion":"Access control","points":20},{"criterion":"Shift stock check","points":25},{"criterion":"Expiry/label/storage checks","points":25}],"subject":"Pharmacology","key":"NSNT:126","points":1},{"type":"SEQ","topic":"2.8","q":"Nyatakan semakan penting sebelum memberi dangerous drug.","answer":"Patient, prescription, registration, dose, time, route dan witness; rekod segera dalam DDA book/BHT/chart dan pastikan stock balance/signature.","rubric":[{"criterion":"Patient/prescription/registration","points":25},{"criterion":"Dose/time/route","points":25},{"criterion":"Witness","points":20},{"criterion":"Record/stock/signature","points":30}],"subject":"Pharmacology","key":"NSNT:127","points":1},{"type":"SEQ","topic":"2.9","q":"Jelaskan autonomy, beneficence, nonmaleficence, justice dan veracity.","answer":"Autonomy=hak membuat keputusan; beneficence=berbuat baik; nonmaleficence=mengelakkan kemudaratan; justice=keadilan; veracity=berkata benar.","rubric":[{"criterion":"Autonomy","points":20},{"criterion":"Beneficence","points":20},{"criterion":"Nonmaleficence","points":20},{"criterion":"Justice","points":20},{"criterion":"Veracity","points":20}],"subject":"Pharmacology","key":"NSNT:128","points":1},{"type":"SEQ","topic":"2.9","q":"Nyatakan empat elemen malpractice.","answer":"Duty, breach of duty, causal connection dan damage.","rubric":[{"criterion":"Duty","points":25},{"criterion":"Breach","points":25},{"criterion":"Causal connection","points":25},{"criterion":"Damage","points":25}],"subject":"Pharmacology","key":"NSNT:129","points":1},{"type":"SEQ","topic":"2.10","q":"Senaraikan 7R dan tiga tambahan 10R.","answer":"7R: Right patient, medication, dose, route, time, to refuse, documentation. Tambahan: assessment, evaluation, client education.","rubric":[{"criterion":"7R lengkap","points":70},{"criterion":"3 tambahan 10R","points":30}],"subject":"Pharmacology","key":"NSNT:130","points":1},{"type":"SEQ","topic":"2.11.1","q":"Terangkan prinsip asas penyediaan ubat oral yang selamat.","answer":"Gunakan kawasan bersih/terang, semak label dan identiti pesakit, ikut prinsip keselamatan, pastikan oral medication diambil/ditelan dan dokumentasi tepat.","rubric":[{"criterion":"Preparation area","points":20},{"criterion":"Checks","points":30},{"criterion":"Administration/swallowing","points":25},{"criterion":"Documentation","points":25}],"subject":"Pharmacology","key":"NSNT:131","points":1},{"type":"SEQ","topic":"2.11.2","q":"Terangkan langkah penting IM injection berdasarkan nota.","answer":"Pilih site sesuai; clean dengan satu stroke keluar dan kering; angle 90°; insert dengan betul; aspirate 0.3–0.5 mL seperti nota; jika darah stop/remove/new drug; inject slowly dan monitor complications.","rubric":[{"criterion":"Site/cleaning","points":20},{"criterion":"90° technique","points":25},{"criterion":"Aspiration 0.3–0.5 mL","points":20},{"criterion":"Action if blood","points":20},{"criterion":"Slow injection/complications","points":15}],"subject":"Pharmacology","key":"NSNT:132","points":1},{"type":"SEQ","topic":"2.11.3","q":"Nyatakan teknik asas eye, ear, nasal dan rectal medication.","answer":"Eye: conjunctiva bukan cornea. Ear infant down/back, adult up/back. Nasal head slightly back. Rectal suppository/enema left lateral.","rubric":[{"criterion":"Eye","points":25},{"criterion":"Ear","points":25},{"criterion":"Nasal","points":20},{"criterion":"Rectal","points":30}],"subject":"Pharmacology","key":"NSNT:133","points":1},{"type":"SEQ","topic":"2.11.4","q":"Terangkan prinsip dokumentasi medication administration.","answer":"Dokumentasi mesti accurate, complete, timely, objective; date/time/signature/name; rekod effects; tandatangan selepas oral medication ditelan; jika tidak diberi kerana muntah, dokumentasikan sebab sebenar.","rubric":[{"criterion":"Accurate/complete/timely/objective","points":35},{"criterion":"Date/time/signature/name","points":20},{"criterion":"Effects/response","points":20},{"criterion":"Not given due vomiting documented correctly","points":25}],"subject":"Pharmacology","key":"NSNT:134","points":1},{"type":"SEQ","topic":"2.11.5","q":"Nyatakan perkara utama patient education tentang ubat.","answer":"Nama, tujuan/action, dose, side effects, how/when/frequency/duration, adherence, risks stopping, label/allergy/expiry, storage, jangan kongsi, reminders, sedation/driving dan follow-up.","rubric":[{"criterion":"Drug purpose/dose/how/when","points":35},{"criterion":"Side effects/adherence/stopping","points":25},{"criterion":"Label/allergy/expiry/storage","points":20},{"criterion":"Safety/no sharing/sedation/follow-up","points":20}],"subject":"Pharmacology","key":"NSNT:135","points":1},{"type":"SEQ","topic":"3.0","q":"Bezakan complementary dan alternative medicine.","answer":"Complementary digunakan bersama rawatan konvensional; alternative menggantikan rawatan konvensional. Safety, ethics dan referral perlu dipertimbangkan.","rubric":[{"criterion":"Complementary","points":40},{"criterion":"Alternative","points":40},{"criterion":"Safety/ethics/referral","points":20}],"subject":"Pharmacology","key":"NSNT:136","points":1},{"type":"SEQ","topic":"2.1","q":"Terangkan onset, peak, duration dan half-life.","answer":"Onset ialah masa kesan mula; peak ialah masa/kepekatan kesan maksimum; duration ialah tempoh kesan; half-life ialah masa untuk jumlah/kepekatan berkurang kira-kira separuh.","rubric":[{"criterion":"Onset","points":25},{"criterion":"Peak","points":25},{"criterion":"Duration","points":25},{"criterion":"Half-life","points":25}],"subject":"Pharmacology","key":"NSNT:137","points":1},{"type":"SEQ","topic":"2.6","q":"Jelaskan mengapa slow-release/enteric-coated tidak boleh dihancurkan sewenang-wenangnya.","answer":"Menghancurkan boleh mengubah pelepasan/penyerapan yang direka bentuk dan menjejaskan keselamatan/keberkesanan; ikut arahan produk/prescriber.","rubric":[{"criterion":"Modified release/absorption concept","points":50},{"criterion":"Safety/effect","points":30},{"criterion":"Follow appropriate instruction","points":20}],"subject":"Pharmacology","key":"NSNT:138","points":1},{"type":"SEQ","topic":"2.8","q":"Apakah kepentingan witness dan rekod bagi dangerous drugs?","answer":"Witness membantu semakan/pengawasan pemberian mengikut polisi; rekod memastikan traceability, stock balance dan accountability.","rubric":[{"criterion":"Witness role","points":45},{"criterion":"Record/traceability","points":35},{"criterion":"Stock/accountability","points":20}],"subject":"Pharmacology","key":"NSNT:139","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order paracetamol 500 mg. Stock tablet 250 mg/tablet. Berapa tablet perlu diberi?","answer":"2 tablet","rubric":[{"criterion":"Formula dose required ÷ stock dose","points":25},{"criterion":"500 ÷ 250","points":25},{"criterion":"2 tablet","points":50}],"subject":"Pharmacology","key":"NSNT:140","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order 750 mg. Stock 500 mg/tablet. Berapa tablet?","answer":"1.5 tablet, jika bentuk tablet membenarkan pecahan mengikut arahan/polisi.","rubric":[{"criterion":"Formula","points":25},{"criterion":"750 ÷ 500","points":25},{"criterion":"1.5 tablet + safety consideration","points":50}],"subject":"Pharmacology","key":"NSNT:141","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order 125 mg. Stock liquid 250 mg/5 mL. Berapa mL?","answer":"2.5 mL","rubric":[{"criterion":"Dose required × volume / stock dose","points":25},{"criterion":"125×5/250","points":35},{"criterion":"2.5 mL","points":40}],"subject":"Pharmacology","key":"NSNT:142","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order 375 mg. Stock 250 mg/5 mL. Berapa mL?","answer":"7.5 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"375×5/250","points":35},{"criterion":"7.5 mL","points":40}],"subject":"Pharmacology","key":"NSNT:143","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order 20 mg. Stock 10 mg/mL. Berapa mL?","answer":"2 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"20÷10","points":25},{"criterion":"2 mL","points":50}],"subject":"Pharmacology","key":"NSNT:144","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order 75 mg. Stock 50 mg/mL. Berapa mL?","answer":"1.5 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"75÷50","points":25},{"criterion":"1.5 mL","points":50}],"subject":"Pharmacology","key":"NSNT:145","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 40 mg. Stock injection 20 mg/mL. Berapa mL?","answer":"2 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"40÷20","points":25},{"criterion":"2 mL","points":50}],"subject":"Pharmacology","key":"NSNT:146","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 125 mg. Stock 250 mg/5 mL. Berapa mL?","answer":"2.5 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"125×5/250","points":35},{"criterion":"2.5 mL","points":40}],"subject":"Pharmacology","key":"NSNT:147","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 75 mg. Stock 100 mg/2 mL. Berapa mL?","answer":"1.5 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"75×2/100","points":35},{"criterion":"1.5 mL","points":40}],"subject":"Pharmacology","key":"NSNT:148","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 30,000 units heparin. Stock 10,000 units/mL. Berapa mL?","answer":"3 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"30000÷10000","points":25},{"criterion":"3 mL","points":50}],"subject":"Pharmacology","key":"NSNT:149","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 60 mg. Stock 40 mg/mL. Berapa mL?","answer":"1.5 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"60÷40","points":25},{"criterion":"1.5 mL","points":50}],"subject":"Pharmacology","key":"NSNT:150","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Semasa IM aspiration keluar darah. Apakah tindakan?","answer":"Hentikan, keluarkan jarum dan gunakan drug baru/site baru mengikut prosedur; jangan inject drug yang telah tercemar.","rubric":[{"criterion":"Stop/remove","points":35},{"criterion":"New drug/site according to procedure","points":35},{"criterion":"Do not inject contaminated preparation","points":30}],"subject":"Pharmacology","key":"NSNT:151","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Suntikan IM disediakan pada 45°. Apakah yang perlu diperbetulkan?","answer":"Semak route, target muscle dan angle; nota menyatakan IM 90°.","rubric":[{"criterion":"Identify incorrect angle","points":30},{"criterion":"90°","points":40},{"criterion":"Target muscle/route","points":30}],"subject":"Pharmacology","key":"NSNT:152","points":1},{"type":"CLINICAL","topic":"2.8","q":"Rekod DDA tidak seimbang selepas satu dose. Apakah tindakan?","answer":"Semak prescription, patient, dose, witness, rekod dan stock balance; laporkan/urus mengikut polisi dan jangan ubah rekod secara tidak sah.","rubric":[{"criterion":"Semak source records","points":35},{"criterion":"Stock/witness/prescription","points":30},{"criterion":"Report/correct according to policy","points":35}],"subject":"Pharmacology","key":"NSNT:153","points":1},{"type":"CLINICAL","topic":"2.8","q":"Kunci ruang DDA ditinggalkan terbuka. Apakah risiko dan tindakan?","answer":"Risiko akses tidak sah; amankan ruang/kunci dan laporkan mengikut polisi.","rubric":[{"criterion":"Risk identified","points":40},{"criterion":"Secure storage","points":30},{"criterion":"Report","points":30}],"subject":"Pharmacology","key":"NSNT:154","points":1},{"type":"CLINICAL","topic":"2.9","q":"Pesakit kompeten menolak ubat. Apakah tindakan?","answer":"Hormati autonomy/Right To Refuse, beri penjelasan sesuai, dengar sebab, dan dokumentasikan refusal serta tindakan.","rubric":[{"criterion":"Autonomy/right to refuse","points":35},{"criterion":"Explanation/communication","points":30},{"criterion":"Documentation","points":35}],"subject":"Pharmacology","key":"NSNT:155","points":1},{"type":"CLINICAL","topic":"2.10","q":"Order lengkap tetapi assessment relevan tidak dibuat. Apakah R 10R yang terlibat?","answer":"Right Assessment; keselamatan pemberian juga perlu dinilai sebelum administration.","rubric":[{"criterion":"Right Assessment","points":60},{"criterion":"Safety before administration","points":40}],"subject":"Pharmacology","key":"NSNT:156","points":1},{"type":"CLINICAL","topic":"2.11.3","q":"Pelatih meletakkan eye drop terus pada cornea. Betulkan teknik.","answer":"Letakkan eye drops pada conjunctiva, bukan cornea.","rubric":[{"criterion":"Conjunctiva","points":60},{"criterion":"Not cornea","points":40}],"subject":"Pharmacology","key":"NSNT:157","points":1},{"type":"CLINICAL","topic":"2.11.4","q":"Ubat tidak diberi kerana muntah tetapi chart ditanda diberi. Kenal pasti kesilapan.","answer":"Documentation error; rekod mesti tepat, lengkap, timely dan objective serta menyatakan sebab ubat tidak diberi.","rubric":[{"criterion":"Identify documentation error","points":40},{"criterion":"Correct principle","points":30},{"criterion":"Reason vomiting recorded","points":30}],"subject":"Pharmacology","key":"NSNT:158","points":1},{"type":"CLINICAL","topic":"2.11.5","q":"Pesakit akan mengambil ubat yang menyebabkan sedation. Apakah pendidikan keselamatan?","answer":"Terangkan risiko mengantuk/sedation dan elakkan memandu atau aktiviti berbahaya jika terjejas; ikut arahan dan maklumkan masalah.","rubric":[{"criterion":"Sedation explained","points":35},{"criterion":"Avoid driving/hazardous activity","points":40},{"criterion":"Follow-up/report concerns","points":25}],"subject":"Pharmacology","key":"NSNT:159","points":1},{"type":"CLINICAL","topic":"2.7","q":"Apex beat pesakit sebelum digoxin ialah 56 bpm. Apakah tindakan?","answer":"Jangan beri digoxin berdasarkan nota; semak/ambil tindakan mengikut arahan dan polisi klinikal serta monitor.","rubric":[{"criterion":"Recognise <60 bpm","points":35},{"criterion":"Hold/do not administer per note","points":40},{"criterion":"Further action/monitor","points":25}],"subject":"Pharmacology","key":"NSNT:160","points":1},{"type":"CLINICAL","topic":"2.7","q":"Pesakit menerima furosemide. Apakah tiga masalah yang perlu dipantau?","answer":"Dehydration, hypokalemia dan hypotension.","rubric":[{"criterion":"Dehydration","points":35},{"criterion":"Hypokalemia","points":35},{"criterion":"Hypotension","points":30}],"subject":"Pharmacology","key":"NSNT:161","points":1},{"type":"CLINICAL","topic":"2.7","q":"Pesakit meminta antibiotik untuk selesema virus. Apakah prinsip penting?","answer":"Antibiotics tidak merawat virus; penggunaan tidak sesuai boleh menyumbang kepada resistance.","rubric":[{"criterion":"Not for viruses","points":50},{"criterion":"Resistance","points":50}],"subject":"Pharmacology","key":"NSNT:162","points":1},{"type":"CLINICAL","topic":"2.6","q":"Pesakit mengambil warfarin dan meningkatkan pengambilan sayuran kaya vitamin K. Apakah isu?","answer":"Food-drug interaction yang perlu dinilai kerana vitamin K berkaitan dengan tindakan warfarin.","rubric":[{"criterion":"Identify interaction","points":45},{"criterion":"Warfarin + vitamin K","points":35},{"criterion":"Safety/education","points":20}],"subject":"Pharmacology","key":"NSNT:163","points":1},{"type":"CLINICAL","topic":"2.6","q":"Pesakit mengambil grapefruit bersama ubat. Apakah tindakan jururawat?","answer":"Kenal pasti potensi food-drug interaction dan semak ubat yang berkaitan/rujuk sumber prescriber atau polisi sebelum meneruskan nasihat.","rubric":[{"criterion":"Identify grapefruit interaction","points":40},{"criterion":"Check specific medication","points":35},{"criterion":"Safety/appropriate referral","points":25}],"subject":"Pharmacology","key":"NSNT:164","points":1},{"type":"CLINICAL","topic":"2.6","q":"Pesakit menerima slow-release tablet dan mahu menghancurkannya. Apakah tindakan?","answer":"Jangan hancurkan sewenang-wenangnya; semak arahan produk/prescriber kerana modified release boleh berubah.","rubric":[{"criterion":"Do not crush routinely","points":45},{"criterion":"Reason modified release","points":30},{"criterion":"Check appropriate instruction","points":25}],"subject":"Pharmacology","key":"NSNT:165","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Medication preparation area gelap dan banyak gangguan. Apakah risiko?","answer":"Risiko medication error; gunakan kawasan bersih, terang dan kurang gangguan.","rubric":[{"criterion":"Medication error risk","points":50},{"criterion":"Clean/bright/low distraction","points":50}],"subject":"Pharmacology","key":"NSNT:166","points":1},{"type":"CLINICAL","topic":"2.11.3","q":"Ear drops untuk infant: bagaimana posisi auricle?","answer":"Tarik auricle down and back.","rubric":[{"criterion":"Down","points":50},{"criterion":"Back","points":50}],"subject":"Pharmacology","key":"NSNT:167","points":1},{"type":"CLINICAL","topic":"2.11.3","q":"Ear drops untuk adult: bagaimana posisi auricle?","answer":"Tarik auricle up and back.","rubric":[{"criterion":"Up","points":50},{"criterion":"Back","points":50}],"subject":"Pharmacology","key":"NSNT:168","points":1},{"type":"CLINICAL","topic":"2.11.3","q":"Klien hendak diberi rectal suppository. Apakah posisi?","answer":"Left lateral position.","rubric":[{"criterion":"Left lateral","points":100}],"subject":"Pharmacology","key":"NSNT:169","points":1},{"type":"CLINICAL","topic":"2.11.4","q":"Apakah maklumat asas yang perlu ada dalam medication documentation?","answer":"Date/time, signature/name dan rekod administration/effect yang tepat, lengkap dan timely.","rubric":[{"criterion":"Date/time","points":30},{"criterion":"Signature/name","points":25},{"criterion":"Administration/effect record","points":45}],"subject":"Pharmacology","key":"NSNT:170","points":1},{"type":"CLINICAL","topic":"2.11.5","q":"Pesakit bertanya apa perlu dibuat dengan ubat yang sudah expired. Apakah pendidikan?","answer":"Jangan gunakan ubat expired; urus/pulangkan mengikut arahan/polisi yang sesuai dan jangan berkongsi ubat.","rubric":[{"criterion":"Do not use expired","points":45},{"criterion":"Return/dispose according to policy","points":35},{"criterion":"Do not share","points":20}],"subject":"Pharmacology","key":"NSNT:171","points":1},{"type":"CLINICAL","topic":"2.11.5","q":"Pesakit mahu berhenti ubat sebaik simptom hilang. Apakah pendidikan?","answer":"Terangkan kepentingan adherence dan risiko berhenti tanpa arahan; ikut tempoh/rawatan yang ditetapkan.","rubric":[{"criterion":"Adherence","points":45},{"criterion":"Risk of stopping","points":30},{"criterion":"Follow prescribed plan","points":25}],"subject":"Pharmacology","key":"NSNT:172","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 150 mg. Stock 300 mg/2 mL. Berapa mL?","answer":"1 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"150×2/300","points":35},{"criterion":"1 mL","points":40}],"subject":"Pharmacology","key":"NSNT:173","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 25 mg. Stock 50 mg/1 mL. Berapa mL?","answer":"0.5 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"25÷50","points":35},{"criterion":"0.5 mL","points":40}],"subject":"Pharmacology","key":"NSNT:174","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Order 80 mg. Stock 40 mg/2 mL. Berapa mL?","answer":"4 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"80×2/40","points":35},{"criterion":"4 mL","points":40}],"subject":"Pharmacology","key":"NSNT:175","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order 1 g. Stock 500 mg/tablet. Berapa tablet?","answer":"2 tablet","rubric":[{"criterion":"Convert 1 g = 1000 mg","points":30},{"criterion":"1000÷500","points":30},{"criterion":"2 tablets","points":40}],"subject":"Pharmacology","key":"NSNT:176","points":1},{"type":"CLINICAL","topic":"2.11.1","q":"Order 250 mg. Stock 125 mg/5 mL. Berapa mL?","answer":"10 mL","rubric":[{"criterion":"Formula","points":25},{"criterion":"250×5/125","points":35},{"criterion":"10 mL","points":40}],"subject":"Pharmacology","key":"NSNT:177","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Sediakan 2% lotion sebanyak 100 mL daripada stock 5%. Berapa mL stock diperlukan?","answer":"40 mL stock 5%, kemudian tambah vehicle/diluent sehingga jumlah 100 mL.","rubric":[{"criterion":"Strength required × volume needed / stock strength","points":30},{"criterion":"2×100/5 = 40 mL","points":40},{"criterion":"Tambah diluent hingga 100 mL","points":30}],"subject":"Pharmacology","key":"NSNT:178","points":1},{"type":"CLINICAL","topic":"2.11.2","q":"Sediakan 1% lotion sebanyak 200 mL daripada stock 4%. Berapa mL stock diperlukan?","answer":"50 mL stock 4%, tambah diluent sehingga 200 mL.","rubric":[{"criterion":"Formula","points":25},{"criterion":"1×200/4 = 50 mL","points":45},{"criterion":"Dilute to 200 mL","points":30}],"subject":"Pharmacology","key":"NSNT:179","points":1}];
